#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
    vector<string> ns(q);
    for (int i = 0; i < q; i++) cin >> ns[i];

    for (long long t = 0; t < q; t++) {
        string d = ns[t];
        size_t mark = d.size();
        for (size_t i = d.size() - 1; i > 0; i--) {
            if (d[i - 1] > d[i]) {
                d[i - 1]--;
                mark = i;
            }
        }
        for (size_t i = mark; i < d.size(); i++) d[i] = '9';
        size_t first = 0;
        while (first + 1 < d.size() && d[first] == '0') first++;
        cout << (t ? " " : "") << d.substr(first);
    }
    cout << "\n";

    return 0;
}

