import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        String[] ns = new String[(int) q];
        for (int i = 0; i < ns.length; i++) ns[i] = next();

        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            char[] d = ns[t].toCharArray();
            int mark = d.length;
            for (int i = d.length - 1; i > 0; i--) {
                if (d[i - 1] > d[i]) {
                    d[i - 1]--;
                    mark = i;
                }
            }
            for (int i = mark; i < d.length; i++) d[i] = '9';
            int first = 0;
            while (first + 1 < d.length && d[first] == '0') first++;
            out.append(t > 0 ? " " : "").append(new String(d, first, d.length - first));
        }
        System.out.println(out);
    }
}
